<script setup lang="ts">
import {ref,onMounted} from 'vue'
import {api,type Question,type Review,type Tag} from './api'
const emit=defineEmits<{open:[paperId:string,number:number]}>()
const rows=ref<(Question & {paper_id:string;paper_title:string;review:Review;tag_labels:string[]})[]>([]),tags=ref<Tag[]>([]),keyword=ref(''),module=ref(''),tag=ref(''),answer=ref(''),error=ref(''),busy=ref(false),summary=ref<{tags:{code:string;label:string;count:number}[]}>()
const modules=['政治理论','常识判断','言语理解与表达','数量关系','判断推理','资料分析']
async function load(){busy.value=true;try{const query=new URLSearchParams({keyword:keyword.value,module:module.value,tag:tag.value,answer_status:answer.value});rows.value=await api('/reviews?'+query);error.value=''}catch(e){error.value=String(e)}finally{busy.value=false}}
onMounted(async()=>{await load();try{tags.value=await api('/tags');summary.value=await api('/analytics/overview')}catch(e){error.value=String(e)}})
</script>
<template><h2>个人复盘知识库</h2><p>跨卷检索你实际记录的心得、方法与标签。点击记录回到原题。</p><div class="toolbar"><el-input v-model="keyword" clearable placeholder="搜索心得 / 标签关键词" @keyup.enter="load"/><el-select v-model="module" clearable placeholder="模块"><el-option v-for="m in modules" :key="m" :value="m"/></el-select><el-select v-model="tag" clearable filterable placeholder="标签"><el-option v-for="t in tags" :key="t.code" :value="t.code" :label="t.label"/></el-select><el-select v-model="answer" clearable placeholder="答题结果"><el-option v-for="(v,k) in {correct:'答对',wrong:'答错',unanswered:'未作答',unknown:'未知'}" :key="k" :value="k" :label="v"/></el-select><el-button @click="load">搜索</el-button></div><el-alert v-if="error" :title="error" type="error"/><div v-loading="busy"><p v-if="!rows.length">没有符合条件的笔记</p><article v-for="r in rows" :key="r.id"><h3><el-button link type="primary" @click="emit('open',r.paper_id,r.number)">{{r.paper_title}} · 第 {{r.number}} 题</el-button></h3><p>{{r.module}} / {{r.subtype||'题型未指定'}} · {{r.answer_status}} · {{r.review.status==='completed'?'已完成':'复盘中'}}{{r.review.review_later?' · 二刷':''}}</p><el-tag v-for="t in r.tag_labels" :key="t">{{t}}</el-tag><p class="note-text">{{r.review.note||'（未填写自由心得）'}}</p><p v-if="r.review.correct_method">正确思路：{{r.review.correct_method}}</p><p v-if="r.review.next_time_rule">下次识别信号：{{r.review.next_time_rule}}</p><small class="muted">更新于 {{new Date(r.review.updated_at||0).toLocaleString()}}</small></article></div><h3>跨卷实际标签频次</h3><p v-if="!summary?.tags.length">尚未记录易错标签</p><el-tag v-for="t in summary?.tags" :key="t.code">{{t.label}} · {{t.count}} 题</el-tag><p class="muted">这些是主动标记次数，不能据此推断所有错题的错因或长期能力。</p></template>
